/* FoodChéri main.min.js */
document.addEventListener("DOMContentLoaded",function(){
/* --- Reveal on scroll --- */
const obs=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add("active")})},{threshold:.1});
document.querySelectorAll(".reveal").forEach(s=>obs.observe(s));

/* --- Menu carousel (JS-generated) --- */
const menuCards=[
  {img:"assets/img/menu_selection/aiguillettes-vegetales.webp",tag:"Végé",title:"Aiguillettes Végétales",sub:"Tomates braisées & pommes de terre"},
  {img:"assets/img/menu_selection/pink-bowl.webp",tag:"Healthy",title:"Pink Bowl",sub:"Explosion de couleurs & vitamines"},
  {img:"assets/img/menu_selection/linguine-saumon.webp",tag:"Mer",title:"Linguine Saumon",sub:"Épinards frais & crème onctueuse"},
  {img:"assets/img/menu_selection/porc-ananas.webp",tag:"Monde",title:"Porc à l'Ananas",sub:"Sucré-salé & riz parfumé"},
  {img:"assets/img/menu_selection/chili-con-carne.webp",tag:"Monde",title:"Chili Con Carne",sub:"Haricots rouges mijotés & épices"},
  {img:"assets/img/menu_selection/green-curry.webp",tag:"Végé",title:"Green Curry Végétal",sub:"Lait de coco, citronnelle & légumes"},
  {img:"assets/img/menu_selection/mousse-marrons.webp",tag:"Dessert",title:"Mousse Marrons",sub:"La douceur du Mont-Blanc"},
  {img:"assets/img/menu_selection/poulet-teriyaki.webp",tag:"Monde",title:"Poulet Teriyaki",sub:"Sauce soja caramélisée & riz sauté"},
  {img:"assets/img/menu_selection/salade-quinoa.webp",tag:"Healthy",title:"Salade Quinoa Coco",sub:"Poulet mariné & fraîcheur exotique"},
  {img:"assets/img/menu_selection/risotto-potimarron.webp",tag:"Végé",title:"Risotto Potimarron",sub:"Champignons des bois & crémeux végétal"}
];
function buildCard(c){
  return`<div class="w-[300px] shrink-0 bg-white rounded-2xl p-4 shadow-lg hover:-translate-y-2 transition-transform duration-300"><div class="h-48 overflow-hidden rounded-2xl mb-4 bg-gray-100 relative"><img loading="lazy" src="${c.img}" class="w-full h-full object-cover hover:scale-110 transition-transform duration-700" alt="${c.title}" width="300" height="192"><span class="absolute top-2 right-2 bg-white px-3 py-1 text-[10px] font-bold uppercase tracking-widest rounded-full text-brand-black">${c.tag}</span></div><h3 class="font-heading text-base mb-1 text-brand-black">${c.title}</h3><p class="text-xs text-gray-500">${c.sub}</p></div>`;
}
const track=document.getElementById("menu-track");
if(track){
  const set1=menuCards.map(buildCard).join("");
  track.innerHTML=set1+set1; /* duplicate for infinite scroll */
}

/* --- Email & Phone validation --- */
const emailInput=document.getElementById("email-input");
const phoneInput=document.getElementById("phone-input");
const validateEmail=e=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(e).toLowerCase());
const validatePhone=p=>/^(?:(?:\+|00)33|0)\s*[1-9](?:[\s.-]*\d{2}){4}$/.test(String(p));
function applyValidity(input,valid){
  if(valid===null){input.className=input.className.replace(/border-(red|green)-300|bg-(red|green)-50|text-(red|green)-900/g,"");input.classList.add("bg-gray-50","border-gray-200");input.setCustomValidity("");}
  else if(valid){input.classList.remove("border-red-300","bg-red-50","text-red-900","bg-gray-50","border-gray-200");input.classList.add("border-green-300","bg-green-50","text-green-900");input.setCustomValidity("");}
  else{input.classList.remove("border-green-300","bg-green-50","text-green-900","bg-gray-50","border-gray-200");input.classList.add("border-red-300","bg-red-50","text-red-900");input.setCustomValidity("Format invalide.");}
}
if(emailInput)emailInput.addEventListener("input",function(){applyValidity(this,this.value===""?null:validateEmail(this.value));});
if(phoneInput)phoneInput.addEventListener("input",function(){applyValidity(this,this.value===""?null:validatePhone(this.value));});

/* --- FAQ Accordion --- */
const faqTriggers=document.querySelectorAll(".faq-trigger");
faqTriggers.forEach(trigger=>{
  trigger.addEventListener("click",function(){
    const item=this.closest(".faq-item");
    const content=item.querySelector(".faq-content");
    const iconWrapper=item.querySelector(".faq-icon");
    const iconEl=iconWrapper?iconWrapper.querySelector("svg"):null;
    const isOpen=this.getAttribute("aria-expanded")==="true";
    /* close all */
    faqTriggers.forEach(t=>{
      if(t!==this){
        const oc=t.closest(".faq-item");
        oc.querySelector(".faq-content").style.maxHeight="0";
        t.setAttribute("aria-expanded","false");
        const ow=oc.querySelector(".faq-icon");
        if(ow){ow.classList.replace("bg-brand-terra","bg-brand-cream");const se=ow.querySelector("svg");if(se){se.classList.replace("text-white","text-brand-terra");setPlusIcon(se);}}
      }
    });
    /* toggle current */
    if(isOpen){
      this.setAttribute("aria-expanded","false");
      content.style.maxHeight="0";
      if(iconWrapper){iconWrapper.classList.replace("bg-brand-terra","bg-brand-cream");if(iconEl){iconEl.classList.replace("text-white","text-brand-terra");setPlusIcon(iconEl);}}
    }else{
      this.setAttribute("aria-expanded","true");
      content.style.maxHeight=content.scrollHeight+"px";
      if(iconWrapper){
        if(iconWrapper.classList.contains("bg-brand-cream"))iconWrapper.classList.replace("bg-brand-cream","bg-brand-terra");
        else iconWrapper.classList.add("bg-brand-terra");
        if(iconEl){if(iconEl.classList.contains("text-brand-terra"))iconEl.classList.replace("text-brand-terra","text-white");else iconEl.classList.add("text-white");setMinusIcon(iconEl);}
      }
    }
  });
});
function setPlusIcon(svg){svg.innerHTML='<line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line>';}
function setMinusIcon(svg){svg.innerHTML='<line x1="5" y1="12" x2="19" y2="12"></line>';}

/* --- Form submission & UTM --- */
const urlParams=new URLSearchParams(window.location.search);
const utmSource=urlParams.get("utm_source");
const utmMedium=urlParams.get("utm_medium");
if(utmSource){const sourceInput=document.getElementById("utm_source");if(sourceInput)sourceInput.value=utmSource;}
if(utmMedium){const mediumInput=document.getElementById("utm_medium");if(mediumInput)mediumInput.value=utmMedium;}

const form=document.getElementById("contact-form");
const submitBtn=document.getElementById("submit-btn");
const successMessage=document.getElementById("success-message");
if(form){
  form.addEventListener("submit",function(e){
    e.preventDefault();
    
    const isEmailValid=emailInput?validateEmail(emailInput.value):true;
    const isPhoneValid=phoneInput?validatePhone(phoneInput.value):true;
    if(!isEmailValid||!isPhoneValid){
      if(emailInput)applyValidity(emailInput,isEmailValid);
      if(phoneInput)applyValidity(phoneInput,isPhoneValid);
      if(!isEmailValid){emailInput.setCustomValidity("Veuillez saisir un e-mail valide.");emailInput.focus();}
      else{phoneInput.setCustomValidity("Veuillez saisir un téléphone valide.");phoneInput.focus();}
      form.reportValidity();
      return;
    }

    const origText=submitBtn.innerHTML;
    submitBtn.innerHTML="Envoi en cours...";
    submitBtn.disabled=true;
    const formData=new FormData(form);
    let tel=formData.get("telephone");
    if(tel){tel=tel.replace(/[\s.-]/g,"");if(tel.startsWith("0"))tel="+33"+tel.substring(1);formData.set("telephone",tel);}
    
    fetch("/",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:new URLSearchParams(formData).toString()})
      .then(()=>{
        window.dataLayer=window.dataLayer||[];
        window.dataLayer.push({event:"generate_lead",form_name:"landing_hello",site_domain:"hello.foodcheri.com",nombre_employes:formData.get("nombre_employes")});
        form.querySelectorAll("input,label,button,select,div.grid").forEach(el=>el.style.display="none");
        successMessage.classList.remove("hidden");
        successMessage.style.opacity="0";
        setTimeout(()=>{successMessage.style.transition="opacity .5s ease-in-out";successMessage.style.opacity="1";},10);
      })
      .catch(()=>{submitBtn.innerHTML=origText;submitBtn.disabled=false;alert("Une erreur est survenue. Veuillez réessayer.");});
  });
}
});
